/* Intermediate 1 · ShopKaro egress, endpoint and two-sided routing. */
(function () {
  const N=AG.aws.n;
  const table=(s,id)=>(s.account.routeTables||[]).find(t=>t.id===id);
  const route=(s,id,dest,target)=>{const t=table(s,id);return !!t&&(t.routes||[]).some(r=>r.destination===dest&&r.target===target&&r.state!=='blackhole');};
  const associated=(s,rt,sub)=>!!table(s,rt)&&(table(s,rt).associations||[]).some(a=>a.subnetId===sub);
  function seed(){
    const specs=[['public-a','10.9.1.0/24','a'],['public-b','10.9.2.0/24','b'],['app-a','10.9.11.0/24','a'],['app-b','10.9.12.0/24','b'],['orders','10.9.21.0/24','a']];
    return {region:'ap-south-1',vpcs:[{id:'vpc-shop',cidr:'10.9.0.0/16',name:'ShopKaro',dnsSupport:true,dnsHostnames:true},{id:'vpc-analytics',cidr:'10.10.0.0/16',name:'Analytics',dnsSupport:true,dnsHostnames:true}],
      subnets:[...specs.map(([name,cidr,az])=>({id:'subnet-'+name,vpcId:'vpc-shop',cidr,az:'ap-south-1'+az,public:false})),{id:'subnet-analytics',vpcId:'vpc-analytics',cidr:'10.10.1.0/24',az:'ap-south-1a',public:false}],
      internetGateways:[{id:'igw-shop',vpcId:'vpc-shop'}],
      routeTables:[...specs.map(([name])=>({id:'rtb-'+name,vpcId:'vpc-shop',routes:[{destination:'10.9.0.0/16',target:'local',type:'local'},...(name.startsWith('public')?[{destination:'0.0.0.0/0',target:'igw-shop',type:'igw'}]:[])],associations:[{id:'rtbassoc-'+name,subnetId:'subnet-'+name}]})),{id:'rtb-analytics',vpcId:'vpc-analytics',routes:[{destination:'10.10.0.0/16',target:'local',type:'local'}],associations:[{id:'rtbassoc-analytics',subnetId:'subnet-analytics'}]}],
      securityGroups:[{id:'sg-app',vpcId:'vpc-shop',name:'app',ingress:[],egress:[{protocol:'tcp',fromPort:443,toPort:443,cidr:'0.0.0.0/0'}]},{id:'sg-orders',vpcId:'vpc-shop',name:'orders-reader',ingress:[{protocol:'tcp',fromPort:5432,toPort:5432,cidr:'10.10.1.0/24'}]}],
      instances:[{id:'i-app-a',name:'app-a',state:'running',vpcId:'vpc-shop',subnetId:'subnet-app-a',az:'ap-south-1a',privateIp:'10.9.11.10',publicIp:null,sgIds:['sg-app']},{id:'i-app-b',name:'app-b',state:'running',vpcId:'vpc-shop',subnetId:'subnet-app-b',az:'ap-south-1b',privateIp:'10.9.12.10',publicIp:null,sgIds:['sg-app']}],
      rds:[{id:'orders-read',name:'orders-reader',engine:'postgres',class:'db.t3.small',state:'available',source:'orders-main',encrypted:true,publicAccess:false,endpoint:'orders-read.sim.ap-south-1.rds.amazonaws.com',storage:20}],
      buckets:[{name:'shop-flowlogs',encryption:true,public:false,objects:[]}],addresses:[],natGateways:[],vpcEndpoints:[],vpcPeerings:[],flowLogs:[],
    };
  }
  function natOK(s,az){
    const n=(s.account.natGateways||[]).find(n=>n.subnetId==='subnet-public-'+az&&n.state==='available'&&n.connectivityType==='public');
    return !!n&&associated(s,'rtb-public-'+az,'subnet-public-'+az)&&associated(s,'rtb-app-'+az,'subnet-app-'+az)&&route(s,'rtb-public-'+az,'0.0.0.0/0','igw-shop')&&route(s,'rtb-app-'+az,'0.0.0.0/0',n.id)&&(s.account.addresses||[]).some(a=>a.allocationId===n.allocationId&&a.natId===n.id);
  }
  function endpointOK(s){
    return (s.account.vpcEndpoints||[]).some(e=>e.type==='Gateway'&&e.serviceName==='com.amazonaws.ap-south-1.s3'&&e.vpcId==='vpc-shop'&&e.state==='available'&&['a','b'].every(az=>(e.routeTableIds||[]).includes('rtb-app-'+az)&&!!table(s,'rtb-app-'+az)&&(table(s,'rtb-app-'+az).routes||[]).some(r=>r.prefixListId===e.prefixListId&&r.target===e.id&&r.state!=='blackhole')));
  }
  function peerOK(s){return (s.account.vpcPeerings||[]).some(p=>p.state==='active'&&[p.requester,p.accepter].includes('vpc-shop')&&[p.requester,p.accepter].includes('vpc-analytics')&&route(s,'rtb-orders','10.10.0.0/16',p.id)&&route(s,'rtb-analytics','10.9.0.0/16',p.id)&&associated(s,'rtb-orders','subnet-orders')&&associated(s,'rtb-analytics','subnet-analytics'));}
  function preserved(s){
    const d=(s.account.rds||[]).find(r=>r.id==='orders-read'),g=(s.account.securityGroups||[]).find(g=>g.id==='sg-orders'),app=(s.account.securityGroups||[]).find(g=>g.id==='sg-app');
    return !!app&&app.ingress.length===0&&app.egress.length===1&&app.egress[0].protocol==='tcp'&&app.egress[0].fromPort===443&&app.egress[0].toPort===443&&app.egress[0].cidr==='0.0.0.0/0'&&!!d&&d.state==='available'&&d.encrypted&&!d.publicAccess&&!!g&&g.ingress.length===1&&g.ingress[0].protocol==='tcp'&&g.ingress[0].fromPort===5432&&g.ingress[0].toPort===5432&&g.ingress[0].cidr==='10.10.1.0/24'&&['a','b'].every(az=>(s.account.instances||[]).some(i=>i.id==='i-app-'+az&&i.state==='running'&&!i.publicIp&&i.subnetId==='subnet-app-'+az))&&(s.account.routeTables||[]).length===6&&(s.account.routeTables||[]).every(t=>t.routes.some(r=>r.target==='local'))&&(s.account.internetGateways||[]).some(g=>g.id==='igw-shop'&&g.vpcId==='vpc-shop');
  }
  const SOLUTION=[
    'aws ec2 allocate-address --domain vpc',
    'aws ec2 allocate-address --domain vpc',
    'aws ec2 create-nat-gateway --subnet-id subnet-public-a --allocation-id eipalloc-000000001',
    'aws ec2 wait nat-gateway-available --nat-gateway-ids nat-000000001',
    'aws ec2 create-nat-gateway --subnet-id subnet-public-b --allocation-id eipalloc-000000002',
    'aws ec2 wait nat-gateway-available --nat-gateway-ids nat-000000002',
    'aws ec2 create-route --route-table-id rtb-app-a --destination-cidr-block 0.0.0.0/0 --nat-gateway-id nat-000000001',
    'aws ec2 create-route --route-table-id rtb-app-b --destination-cidr-block 0.0.0.0/0 --nat-gateway-id nat-000000002',
    'aws ec2 create-vpc-endpoint --vpc-id vpc-shop --vpc-endpoint-type Gateway --service-name com.amazonaws.ap-south-1.s3 --route-table-ids rtb-app-a rtb-app-b',
    'aws ec2 create-vpc-peering-connection --vpc-id vpc-shop --peer-vpc-id vpc-analytics',
    'aws ec2 accept-vpc-peering-connection --vpc-peering-connection-id pcx-000000001',
    'aws ec2 create-route --route-table-id rtb-orders --destination-cidr-block 10.10.0.0/16 --vpc-peering-connection-id pcx-000000001',
    'aws ec2 create-route --route-table-id rtb-analytics --destination-cidr-block 10.9.0.0/16 --vpc-peering-connection-id pcx-000000001',
  ];
  function bill(k){
    const natGB=k.internet+(k.endpoint?0:k.s3),crossGB=natGB*Math.max(0,k.azs-k.nats)/k.azs;
    // Explicit aggregate cross-AZ allowance, not a universal AWS transfer quote.
    const cross=crossGB*0.02,fixed=k.nats*(0.045+0.005)*730,processing=natGB*0.045,total=fixed+processing+cross;
    const resilient=k.nats===k.azs,ok=k.s3>=1024&&k.internet>=100&&k.endpoint===1&&resilient&&total<=120;
    return {natGB,crossGB,cross,fixed,processing,total,resilient,ok,saved:k.endpoint?k.s3*0.045:0};
  }
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'vpcdeep',icon:'🌐',title:'VPC Deep Dive: private app ka bahar jaane ka raasta aur NAT ka bill',badge:'Network Navin',
    hook:{when:'ShopKaro · demo ke baad poore desh mein launch · course ki kahani (fictional)',title:'"S3 images private hain. NAT bill mein images ka charge kyun?"',text:'Ravi ne app ko private subnets mein shift kiya. Priya ka payment verification aur package download bahar internet par jaate hain. Neha ne bill dekha: S3 photos ka 1,024 GB/mahina traffic bhi NAT se ho kar ja raha tha, aur NAT har GB ka paisa leta hai. Analytics team ki alag VPC orders replica tak nahi pahunch pa rahi. Teen kaam hain, teen alag raaste chahiye: private app ka internet, S3 tak sasta raasta, aur analytics ka connection. Pehle click karke dekho ki har packet ka route kaise decide hota hai.'},
    objectives:['<b>Bahar ka raasta (egress)</b>: zonal NAT, Regional NAT, NAT instance aur IPv6 egress-only gateway compare karo','<b>Endpoints</b>: S3 gateway endpoint (route se) vs interface endpoint (ENI + DNS + SG) samjho','<b>Peering</b>: accept karna + dono taraf route, CIDR overlap nahi, transit nahi','<b>Scale ka faisla</b>: full mesh N×(N−1)/2 vs TGW attachments aur segmentation','<b>Debugging</b>: route ka saboot, Flow Logs aur Reachability Analyzer kya bata sakte hain aur kya nahi','<b>Hands-on</b>: NAT/EIP, S3 endpoint, dono taraf ka peer repair aur sirf apne resources ka cleanup'],
    steps:[
      {q:'Private IPv4 wale app ko internet kaise milega? Andar aane wale webhook ka raasta alag kyun hai?',analogy:'Society ke flat ka sadak wala darwaza band hai. Par resident delivery counter se bahar order bhej sakta hai. Counter us order ka jawaab wapas le aata hai. Koi anjaan aadmi counter se naya visit shuru nahi kar sakta.',body:'<div class="tbl-wrap"><table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Kya dena padta hai</th></tr><tr><td>Private IPv4 → payment API</td><td>Public NAT + IGW ka raasta</td><td>Ghante + GB + IPv4 ka bill (AWS managed)</td></tr><tr><td>Apna middlebox ya poora control</td><td>NAT instance</td><td>EC2 patching, source/destination check band karna, capacity aur failover: sab team ka kaam</td></tr><tr><td>Sirf IPv6 bahar jaana</td><td>Egress-only IGW, ::/0 route</td><td>Address translation nahi; sirf IPv6 raasta; network rules phir bhi lagte hain</td></tr></table></div>',points:['Zonal public NAT ka setup: NAT public subnet mein, Elastic IP (EIP) ke saath. App ka default route → NAT. NAT wale subnet ka default route → IGW. App ko public IPv4 ki zaroorat nahi.','NAT Gateway par SG nahi lagta. App ka SG/NACL, DNS, destination ka chalu hona aur NAT ki capacity alag se check karo.','Payment provider ka webhook (jo bina poochhe andar aata hai) HTTPS ALB se app tak aata hai. App ka verification request bahar NAT se jaata hai. Callback ko NAT se andar aana mat samjho.'],asli:'Kaam: lab setup ke baad private app ka route table dekho. Sirf local route mila? Matlab internet ka default raasta hai hi nahi. Subnet ko "private" naam dene se raasta nahi banta.'},
      {q:'Zonal NAT aur Regional NAT mein AZ fail hone par kya farak hai?',analogy:'Zonal NAT ek wing ka delivery counter hai. Regional NAT ek service hai jo un saare wings mein counter chalati hai jahan app chal rahi hai. Ek service ID ka matlab yeh nahi ki bill sirf ek wing ka aayega.',body:'<div class="tbl-wrap"><table><tr><th>Mode</th><th>Kahan aur kaise route</th><th>Faisla</th></tr><tr><td>Zonal public NAT</td><td>Ek AZ ke public subnet mein; har app AZ apna NAT use kare</td><td>Har AZ ka apna route aur EIP; lab ka simple model</td></tr><tr><td>Regional NAT</td><td>VPC level par regional mode; app jin AZ mein hai wahan apne aap phailta hai</td><td>Ek regional NAT ID; AZ ka mel service khud sambhalti hai; aaj ki availability/config check karo</td></tr></table></div>',points:['AZ-a ka akela zonal NAT agar AZ-b bhi use kare, toh AZ-b AZ-a par tik jaata hai, aur cross-AZ data ka charge bhi lag sakta hai. NAT "available" dikhne se IGW route sahi hai, yeh prove nahi hota.','Regional NAT AWS docs mein aaj ka option hai. Regional mode mein gateway ke liye public subnet zaroori nahi. Bill har configured AZ-ghante aur processed GB par banta hai; ek ID ka matlab ek AZ-ghanta nahi.','Exam mein agar "zonal public NAT + do AZ" likha ho, toh har AZ mein ek NAT + usi AZ ka route chuno. Par yeh mat bolo ki "har NAT hamesha ek hi AZ mein hota hai"; Regional NAT bhi ek option hai.'],asli:'Simulator aur lab jaan-boojh kar zonal NAT sikhate hain. Regional NAT ka phailna aur AZ fail hone ka time yahan test nahi hua.'},
      {q:'S3 ka traffic NAT se kaise hataoge? Kya endpoint permission bhi deta hai?',analogy:'Mall ke warehouse ke liye ek alag maal-gate hai. Gate sirf likhe hue warehouse tak jaata hai. Gate ka badge stock uthane ki permission nahi deta.',body:'<p><b>Gateway endpoint</b> S3 aur DynamoDB ke liye hai. Ise route table se jodte hain. AWS ek managed prefix-list route jod deta hai. Usi region ke S3 ka yeh route 0.0.0.0/0 se zyada specific hai, isliye S3 traffic is raaste jaata hai. Baaki internet, doosri APIs aur doosre region ki service is endpoint se nahi jaate.</p>',points:['Gateway endpoint ka koi extra ghante ka ya data processing ka charge nahi. S3 storage, requests aur lagu transfer charges phir bhi lagte hain.','Endpoint policy ek extra boundary hai. IAM role, bucket policy aur explicit Deny phir bhi check hote hain. Endpoint banane se GetObject ki permission nahi milti, na public access khulta hai.','Gateway endpoint ko peering, TGW ya VPN ke raaste share hone wala gateway mat samjho. Doosri VPC ya on-prem se S3 chahiye, toh interface endpoint wala design review karo.','Chalao: aws ec2 describe-route-tables. DestinationPrefixListId → vpce target dekho. Jis table se endpoint juda nahi, woh S3 ko purane NAT/default route par bhej sakti hai.'],asli:'Gateway endpoint poori service tak private raasta hai. Private photo dekhne ki permission aur CloudFront origin policy alag boundaries hain.'},
      {q:'Secrets Manager aur ECR ke liye gateway route kaafi kyun nahi?',analogy:'Har khaas dukaan ka apna private service desk chahiye. Ek S3 maal-gate se payment, secret store aur container registry ke saare counters nahi milte.',body:'<p><b>Interface endpoint</b> chune hue AZ subnets mein private ENIs (network cards) banata hai. Private DNS on ho, toh service ka public hostname in private IPs par resolve hota hai. Iske liye VPC ka DNS support/hostnames on hona chahiye, aur endpoint SG par inbound 443 allow.</p>',points:['Ek interface endpoint har AZ mein sirf ek subnet chun sakta hai. Kai AZ mein ENI ho toh resilience aur locality behtar. Bill har endpoint/service × AZ × ghante ka hota hai.','ECR se private image pull ke liye aksar ecr.api + ecr.dkr interface endpoints, aur image layers ke liye S3 gateway endpoint chahiye. Logs jaisi baaki cheezein workload ke hisaab se jodo. Ek endpoint saari AWS services cover nahi karta.','PrivateLink mein provider ki service NLB ke peeche ho sakti hai. Consumer ka interface endpoint connection shuru karta hai. Yeh sirf service ka access hai, provider ka poora network nahi. Naye resource aur VPC Lattice options alag se dekho.'],example:'<div class="war-story"><b>Galti jo sab karte hain:</b> PrivateDNS=true dekh kar maan lena ki SDK call chal jaayegi. Endpoint SG par 443, VPC DNS settings, NACL, IAM ya service policy mein galti ho toh call phir bhi fail ho sakti hai.</div>',asli:'Lab dikhata hai: interface endpoint Type=Interface, PrivateDNS=true aur ENIs=2. Asli DNS lookup ya SDK se secret padhna Moto prove nahi karta.'},
      {q:'Analytics VPC orders replica tak kaise pahunchegi?',analogy:'Do societies ke beech seedha gate khul gaya. Par dono societies ke road signs badalne padenge. Wapas aane wali delivery ko bhi sahi gate ka raasta chahiye.',body:'<pre>Analytics: 10.10.0.0/16\n  destination 10.9.0.0/16\n  → active pcx connection\nOrders route table:\n  destination 10.10.0.0/16\n  → same active pcx</pre>',points:['Peering request banao, phir doosri taraf accept karo: tab connection active hota hai. Phir bhi dono taraf ke subnet route tables, SG/NACL ports aur app ki permission chahiye.','Dono VPC ke CIDR overlap nahi ho sakte. A↔B aur B↔C hone se A↔C nahi banta (transit nahi hota). Doosri VPC ka NAT, IGW ya gateway endpoint peering se share nahi hota.','Peering same ya alag account, aur same ya alag region mein ho sakti hai. Par SG reference aur DNS ke niyam alag hain. Yeh simulator sirf same-region model karta hai; cross-region mana karna AWS ki limit nahi hai.','Example: analytics workers 10.10.1.0/24 ko sirf orders reader ke PostgreSQL 5432 ka access do. DB par 0.0.0.0/0 kholna route ka fix nahi hai.'],asli:'Active pcx sirf ek saboot hai. Ek taraf ka route dekh kar connection chal raha hai, yeh mat maano. Wapas aane wali table bhi dekho.'},
      {q:'Peering mesh kab Transit Gateway hub mein badalna chahiye?',analogy:'Har dukaan se har dukaan tak alag private pul banana bahut jhanjhat hai. Ek common transport hub pul kam kar deta hai. Par hub ke signs aur allowed jagahein phir bhi set karni padti hain.',body:'<div class="tbl-wrap"><table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Limit / kharcha</th></tr><tr><td>Kuch seedhe VPC connections</td><td>Peering</td><td>Transit nahi; dono taraf routes aur security</td></tr><tr><td>Bahut saari VPCs/on-prem + segmentation</td><td>Transit Gateway</td><td>Attachments, VPC routes aur TGW tables/propagation chahiye</td></tr><tr><td>Sirf ek shared API, customers ke CIDR overlap</td><td>PrivateLink service endpoint</td><td>Sirf service ka access, poora network mesh nahi</td></tr></table></div>',points:['Full mesh mein N VPCs ke liye N×(N−1)/2 connections. 5 VPCs → 10 peers; 10 VPCs → 45. Ek TGW hub aur 10 VPCs → 10 attachments, plus route aur segmentation ka design.','Maan lo ShopKaro ke 40 accounts aur 120 VPCs hain. Tab attachment ki fees se zyada central segmentation kaam ki ho sakti hai. Hum yeh nahi keh rahe ki har badi company yahi design chalati hai.','TGW transit kar sakta hai, iska matlab yeh nahi ki har VPC har VPC tak pahunche. Prod aur dev ke route table association aur propagation soch-samajh kar set karo.'],asli:'Kaun kis se baat karega (connectivity matrix) aur chalane ka kharcha dekh kar chuno. "5 VPC ke baad TGW" jaisa koi fixed rule nahi. TGW/hybrid ka poora lab Advanced networking mein aayega.'},
      {q:'Timeout debug karte waqt logs aur path analyzer kya prove karte hain?',analogy:'Courier tracking batati hai ki parcel kis pate par kab pahuncha. Shehar ka naksha planned raasta batata hai. Tracking parcel ke andar ka saamaan nahi dikhati. Naksha asli traffic jam test nahi karta.',body:'<div class="tbl-wrap"><table><tr><th>Saboot</th><th>Kis kaam ka</th><th>Limit</th></tr><tr><td>Routes + associations</td><td>Source subnet ka asli raasta aur wapsi ka route</td><td>Route sahi hone se app/SQL ready hai, yeh prove nahi</td></tr><tr><td>VPC Flow Logs</td><td>ENI ka IP/port/ACCEPT/REJECT data</td><td>Packet ka andar ka data nahi; har tarah ka traffic log nahi hota</td></tr><tr><td>Reachability Analyzer</td><td>Config ke hisaab se raasta aur kaun rok raha hai</td><td>Asli packet ya app health ka test nahi</td></tr></table></div>',points:['Debug ka order: source, destination, protocol aur port likho → source ka asli route table → NAT/peer/endpoint ki state → wapsi ka route aur SG/NACL → DNS/IAM/app ka saboot.','NAT "available" ho sakta hai, phir bhi subnet ka route sirf local ho. Route ki kami ko app code, CPU scaling ya poori duniya ke liye khule SG se mat chhupao.','Flow Logs CloudWatch Logs, S3 ya Firehose mein ja sakte hain. Delivery permissions aur storage/ingestion ka kharcha dhyaan rakho. Subscription ACTIVE hona logs pahunch gaye, iska saboot nahi.'],asli:'Production mein aisa hota hai: kisi ne NAT-a wale subnet ka public route badal diya, aur app-a/app-b par timeouts aane lage. NAT ka status green hi raha. Isliye dono route hops dekho.'},
      {q:'1,024 GB S3/mahina par NAT ka bill kitna bach sakta hai?',analogy:'Alag warehouse gate ka fayda: delivery counter ki har parcel wali fees bachti hai. Internet API ki delivery ke liye counter abhi bhi chahiye. Counter ka kiraya apne aap zero nahi hota.',body:'<p>Practice ka hisaab, US East list rate, lagbhag 2025–26; mahine mein 730 ghante; ₹88 = $1. Zonal NAT ≈ $0.045/ghanta + $0.045/GB processed; public IPv4 ≈ $0.005/ghanta. Do NAT + EIP ka fixed kharcha ≈ 2×($0.045+$0.005)×730 = <b>$73/mahina</b>. 1,024 GB S3 × $0.045 ≈ <b>$46.08/mahina ≈ ₹4,055/mahina</b> ki processing gateway endpoint se bachti hai. 100 GB internet API traffic par NAT processing ≈ $4.50 phir bhi lagta hai.</p><p>Interface endpoint example ≈ $0.01 har endpoint/AZ/ghanta + pehle tier mein $0.01/GB: do AZ ≈ $14.60/mahina fixed, har endpoint/service. TGW example ≈ $0.05 har VPC attachment/ghanta + $0.02/GB processed; region aur traffic ka raasta bill badalte hain.</p>',points:['Planner shared NAT ke traffic par cross-AZ ka $0.02/GB maan kar chalta hai. Yeh course ka maana hua number hai, asli invoice nahi. Internet transfer, extra endpoints/logs, storage, tax aur daam ke badlav isme nahi jode.','Sahi example: do AZ, do local NAT, S3 endpoint on, S3 1,024 GB aur internet 100 GB → lagbhag $77.50/mahina = ₹6,820/mahina.','Agar supported services ka traffic chhota hai aur NAT pehle se hai, toh bahut saare paid interface endpoints ka fayda nahi bhi ho sakta. Compliance ya private access ki zaroorat aur har service/AZ ka kul kharcha dekh kar faisla karo.'],asli:'Bekaar S3 processing hataane ke liye gateway endpoint lagao. Payment aur package ke liye internet chahiye, toh resilient NAT wala raasta bhi rakho.'},
    ],
    myth:[{myth:'NAT Gateway hamesha sirf ek AZ mein hi chalta hai',sach:'Zonal NAT ek AZ ka hai. Aaj ka Regional NAT app wale saare AZ apne aap cover kar sakta hai. Dono ka kharcha aur setup alag hai.'},{myth:'S3 endpoint bana diya, toh IAM GetObject ki permission bhi mil gayi',sach:'Endpoint sirf network ka raasta hai. Endpoint policy ek extra boundary hai. IAM, bucket policy aur Deny phir bhi lagte hain.'},{myth:'Peering active hai, matlab dono VPC baat kar rahi hain',sach:'Subnets ke dono taraf ke routes, SG/NACL, DNS aur service permission alag se chahiye.'},{myth:'TGW attach kar diya, toh prod/dev ka transit apne aap safe hai',sach:'TGW hub routing kar sakta hai. Par soch-samajh kar associations, propagation, VPC routes aur segmentation set karne padte hain.'}],
    playbook:{title:'Pehle tay karo ki private app ko jaana kahan hai',use:['Internet ka koi bhi IPv4 → review kiya hua public NAT ka raasta','VPC se same-region S3/DynamoDB → gateway endpoint','Supported AWS API ya private service → interface endpoint, DNS/SG/policy ke saath','Kuch poore network connections → peering; bahut saare networks/hybrid → TGW socho'],avoid:['NAT ko andar aane wale webhook ka darwaza samajhna','Peering se doosri VPC ke NAT ya gateway endpoint ka transit expect karna','Endpoints badhate jaana aur har service/AZ ka fixed bill bhool jaana'],how:['Source subnet ka association aur destination ka exact route pehchano','Zonal mode mein usi AZ ka NAT/IGW route; endpoint ka service prefix vs default route compare karo','Peer accept hua, dono routes hain, aur sirf zaroori ports khule hain: yeh check karo','Config ke saboot ke baad asli DNS, SDK/app aur recovery test chalao'],redflags:['NAT available hai, par subnet mein IGW route nahi','Endpoint sirf ek app table se juda hai','Peer route sirf ek taraf; CIDR overlap; bahar ka raasta ek AZ ka shared','ACTIVE Flow Log subscription ko packet pahunchne ka saboot bolna'],rule:'Faisla kaise karein: internet ki koi bhi jagah? NAT. Same-region S3/DynamoDB? Gateway endpoint. Supported service ki private API? Interface endpoint. Poora VPC network? Peering/TGW, dono taraf soch-samajh kar routes.'},
    exam:[{cue:'"private IPv4 instances need internet"',pick:'Public NAT path',why:'Private default route → NAT, NAT subnet → IGW; public NAT EIP use karta hai.'},{cue:'"two AZs; zonal NAT; resilient egress"',pick:'One zonal NAT per AZ and local routes',why:'Fail hui NAT wali AZ ki wajah se bachi AZ nahi tootni chahiye.'},{cue:'"NAT cost mostly same-region S3"',pick:'Gateway endpoint on correct route tables',why:'Us raaste ke liye endpoint ka koi extra ghante ya processing ka charge nahi.'},{cue:'"private Secrets Manager/SQS calls"',pick:'Interface endpoint',why:'Private ENI + DNS + SG par 443 + IAM/service policy.'},{cue:'"A–B and B–C peered, A–C required"',pick:'Direct A–C peer or reviewed transit hub',why:'Peering is non-transitive.'},{cue:'"VPC CIDRs overlap"',pick:'Cannot peer directly',why:'CIDR badlo, ya jahan theek ho wahan service-level PrivateLink dekho.'},{cue:'"native IPv6 outbound-only"',pick:'Egress-only IGW',why:'IPv6 route ::/0; bahar se bina poochhe connection andar nahi aata.'},{cue:'"who connected/rejected at ENI"',pick:'VPC Flow Logs',why:'IP flow ka data, poora payload ya app trace nahi.'},{cue:'"Regional NAT mode"',pick:'Automatic workload-AZ expansion; per-AZ billing',why:'Aaj ka option hai; yeh mat maano ki ek service ID = ek zonal ghante ka charge.'}],
    stages:[
      {type:'dryrun',title:'🔍 S3 bill ka route aur analytics ka wapsi ka raasta',goal:'Har "Agla" click par ek routing change dekho. Service prefix vs default route, aur missing wapsi route: in do sawaalon ka jawaab do.',nodes:[N('ec2',130,95,{label:'private app'}),N('rt',390,95),N('s3',780,95),N('nat',350,270,{label:'zonal NAT-a'}),N('igw',610,270),N('internet',880,270,{label:'Payment API'}),N('ec2#analytics',140,435,{label:'analytics'}),N('pcx',450,435),N('rds',780,435,{label:'orders reader'})],groups:[{label:'App subnet',x:20,y:30,w:220,h:115,kind:'private'},{label:'Public NAT subnet',x:240,y:205,w:220,h:115,kind:'public'},{label:'Analytics VPC',x:20,y:365,w:240,h:145,kind:'vpc'},{label:'Orders subnet',x:660,y:365,w:290,h:145,kind:'private'}],edges:[{from:'ec2',to:'rt'},{from:'rt',to:'s3',dashed:true},{from:'rt',to:'nat'},{from:'nat',to:'igw'},{from:'igw',to:'internet'},{from:'igw',to:'s3',dashed:true},{from:'ec2#analytics',to:'pcx'},{from:'pcx',to:'rds'}],panels:[{id:'cost',title:'Route / NAT subtotal'},{id:'peer',title:'Analytics / return route'}],steps:[
        {clock:'before',say:'App route table mein sirf local + default NAT route hai. Isliye S3 photos ka traffic bhi NAT se ja raha hai, aur har GB ka meter chal raha hai.',flows:[{from:'ec2',to:'rt',tone:'ok'},{from:'rt',to:'nat',label:'0.0.0.0/0',tone:'slow'},{from:'nat',to:'igw',tone:'slow'},{from:'igw',to:'s3',tone:'slow'}],panels:{cost:['1,024 GB S3/mahina × lagbhag $0.045/GB','$46.08/mahina ki bachne wali NAT processing'],peer:['Analytics/ShopKaro peer abhi accept nahi hua']}},
        {clock:'endpoint',say:'Gateway endpoint app route table se jud gaya. AWS ne same-region S3 ka managed prefix-list route jod diya. Default NAT route baaki internet ke liye bana rehta hai.',flows:[{from:'rt',to:'s3',label:'S3 service prefix',tone:'ok'}],ask:{q:'S3 ka service prefix aur default route, dono match karte hain. Traffic kaunsa raasta lega?',choices:['Zyada specific S3 prefix-list route jeetta hai, toh traffic endpoint se jaata hai','Pehle bana default route jeetta hai, kyunki table ka order hi priority hai','NAT route jeetta hai, kyunki NAT ke paas Elastic IP address hai','Dono routes har request ki copy bhejte hain, taaki availability badhe'],answer:0,explain:'Routing "sabse lamba prefix jeete" niyam se chalti hai; row ka order ya EIP priority nahi hai. Zyada specific service route default ko hara deta hai. Requests ki copy nahi banti.'},panels:{cost:['Jude hue app table par S3 ki NAT processing bachi','Endpoint route S3 ki IAM permission nahi deta']}},
        {clock:'payment',say:'Payment provider internet ki koi bhi jagah hai; woh S3 prefix se match nahi karta. Isliye payment verification ab bhi default NAT → IGW se jaata hai. Provider ka andar aane wala webhook public ALB ka alag raasta hai.',flows:[{from:'rt',to:'nat',tone:'ok'},{from:'nat',to:'igw',tone:'ok'},{from:'igw',to:'internet',tone:'ok'}],panels:{cost:['S3 ka shortcut baaki internet ka raasta nahi hataata','NAT ka fixed ghante ka + API ke GB ka charge bacha rehta hai']}},
        {clock:'peer accepted',say:'Peering active ho gaya. Analytics table mein 10.9.0.0/16 → pcx route hai. Par orders table mein analytics ka wapsi route nahi hai. SG 5432 pehle se sahi hai. Sirf active pcx kaafi nahi.',nodes:{pcx:{tone:'ok',badge:'active'}},flows:[{from:'ec2#analytics',to:'pcx',tone:'slow'},{from:'pcx',to:'rds',tone:'slow'}],panels:{peer:['Analytics ka bahar jaane ka route hai','Orders ka wapsi route 10.10.0.0/16 nahi hai']},ask:{q:'Connection timeout ka sabse seedha repair kya hai?',choices:['Orders subnet ki table mein analytics CIDR ka route usi active peer par jodo','DB par inbound 5432 poori duniya ke liye kholo; wapsi route apne aap aa jaayega','Ek aur S3 gateway endpoint banao; PostgreSQL bhi S3 prefixes ke peeche jaata hai','NAT ke EIP ko analytics ka DNS naam de do; peering transit karne lagegi'],answer:0,explain:'Jawaab ke liye orders ki asli table mein peer route chahiye. Bada ingress rule route nahi banata. S3 endpoint aur EIP/DNS PostgreSQL ko route nahi karte, na transit jodte hain.'}},
        {clock:'return fixed',say:'Orders table mein 10.10.0.0/16 → active pcx route jud gaya. Dono taraf ke sahi routes + pehle se lagi SG/NACL/DB permissions se raasta poora hua. Asli SQL aur DNS test phir bhi chahiye.',flows:[{from:'rds',to:'pcx',label:'reply route',tone:'ok'},{from:'pcx',to:'ec2#analytics',tone:'ok'}],panels:{peer:['Dono subnets ki route tables sahi hain','CIDR overlap nahi; galti se transit nahi']}},
        {clock:'review',say:'Teen alag faisle: internet ke liye NAT, same-region S3 ke liye gateway endpoint, analytics ke liye seedha peer aur dono routes. Regional NAT aur TGW alag problems solve karte hain; naamon ko ek jaisa mat samjho.',panels:{cost:['Bekaar processing hatao, zaroori resilience rakho'],peer:['Pehle config review; phir asli packet/app test']}},
      ],lesson:'Zyada specific route tay karta hai ki packet kahan jaayega. Resource ka active status, network permission aur app ka chalna: teeno alag saboot hain.'},
      {type:'flowlab',title:'🎛️ NAT bill board: S3 shortcut ke saath AZ resilience',goal:'Kam se kam 1,024 GB/mahina S3 aur 100 GB/mahina internet traffic chalao. Har active AZ mein ek zonal NAT, S3 endpoint on, aur kharcha lagbhag $120/mahina ke andar rakho. Traffic kam karke goal paar karna nahi chalega.',scenario:'Mahina = 730 ghante; ₹88 = $1; US East 2025–26 ke lagbhag daam: NAT $0.045/ghanta + $0.045/GB, IPv4 $0.005/ghanta. Traffic saare AZ mein barabar maana hai. Shared NAT par cross-AZ ka $0.02/GB course ka maana hua number hai, sab bills par lagu nahi. Storage, requests, logs, interface endpoints, internet transfer aur tax alag.',knobs:[{id:'s3',label:'S3 traffic',min:512,max:2048,step:512,value:1024,unit:' GB/month'},{id:'internet',label:'Internet APIs/packages',min:50,max:200,step:50,value:100,unit:' GB/month'},{id:'azs',label:'Active AZs',min:2,max:3,step:1,value:2},{id:'nats',label:'Zonal NAT count',min:1,max:3,step:1,value:1},{id:'endpoint',label:'S3 gateway endpoint',min:0,max:1,step:1,value:0,labels:{0:'Off / S3 via NAT',1:'On / dono app tables'}}],model:k=>{const b=bill(k);return {readouts:[{label:'Approx monthly subtotal',value:'$'+b.total.toFixed(2)+' · ₹'+Math.round(b.total*88),tone:b.total<=120?'ok':'bad'},{label:'NAT fixed / processing',value:'$'+b.fixed.toFixed(2)+' / $'+b.processing.toFixed(2)+' per month',tone:'info'},{label:'Cross-AZ allowance',value:b.crossGB.toFixed(0)+' GB · $'+b.cross.toFixed(2)+'/month',tone:b.crossGB===0?'ok':'warn'},{label:'Avoided S3 NAT processing',value:'$'+b.saved.toFixed(2)+'/month',tone:k.endpoint?'ok':'bad'},{label:'AZ-loss dependency',value:b.resilient?'Har AZ ka apna zonal NAT route maana gaya':'Har AZ ek NAT wale design ke liye NAT kam ya zyada hain',tone:b.resilient?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Traffic, har AZ ka bahar ka raasta aur endpoint ke goal kharche ke andar pass hue. Asli routes, failure ka behaviour aur poora bill alag se check karo.':'S3 ≥ 1,024 GB/mahina aur internet ≥ 100 GB/mahina rakho; NAT ki ginti = AZ ki ginti aur endpoint On karo. Example: 2 AZ/2 NAT par default traffic ka kharcha lagbhag $77.50/mahina.'}};},check:k=>bill(k).ok,lesson:'Example: 1,024 GB S3, 100 GB internet, 2 AZ, 2 NAT, endpoint On → fixed $73 + API processing $4.50 = lagbhag $77.50/mahina (₹6,820/mahina). Itne hi NAT bina endpoint ke ho toh S3 processing ke lagbhag $46.08 aur judte hain.'},
      {type:'bins',title:'🧭 Destination → correct path',instructions:'Zaroorat dekh kar chuno. NAT, endpoint aur poore network ka connection teen alag kaam hain.',bins:[{id:'nat',label:'Public NAT'},{id:'gateway',label:'Gateway endpoint'},{id:'interface',label:'Interface endpoint'},{id:'peer',label:'Peering'},{id:'tgw',label:'Transit Gateway'}],items:[{text:'Private IPv4 app → bahar ka payment HTTPS API',bin:'nat',explain:'Aam IPv4 internet ke liye; andar aane wala webhook ALB se alag aata hai.'},{text:'Apni VPC se same-region S3 photos padhna',bin:'gateway',explain:'Service prefix route; gateway endpoint ka koi extra ghante ya processing charge nahi.'},{text:'Private AWS service ENI se Secrets Manager',bin:'interface',explain:'PrivateLink endpoint; DNS/SG/IAM phir bhi chahiye.'},{text:'Do VPCs jinke CIDR overlap nahi; seedhe private network routes',bin:'peer',explain:'Kuch hi seedhe connections; dono taraf routes aur security chahiye.'},{text:'120 VPCs/hybrid, control kiye hue transit segments ke saath',bin:'tgw',explain:'Hub attachments aur soch-samajh kar route table segmentation.'},{text:'Private ECR API endpoint aur registry endpoint',bin:'interface',explain:'ecr.api/ecr.dkr, aur image layers ke liye S3 gateway; baaki dependencies workload par depend.'}]},
      {type:'order',title:'🧱 Zonal public NAT ka raasta kis order mein banao',instructions:'Pehle se bane VPC aur IGW ke saath ek tay order mein banao; public routing aur ready hona check karo.',steps:[{text:'Public subnet ki route table mein IGW ka default route jodo aur check karo',explain:'NAT wale subnet ka internet hop pehle saaf hona chahiye; "public" naam kaafi nahi.'},{text:'VPC ke liye Elastic IP allocate karo',explain:'Public zonal NAT ko allocation ID chahiye; har AZ ka allocation alag hota hai.'},{text:'Public subnet mein allocation ID se NAT banao',explain:'NAT chune hue AZ ka hai; app ke private subnet ko NAT ka ghar mat samjho.'},{text:'NAT ka available waiter/state check karo',explain:'Pending resource ko chalne wala raasta mat samjho; asli AWS mein banne mein time lagta hai.'},{text:'Usi AZ ki private app table ka default route NAT ki taraf karo',explain:'Private app ka bahar ka traffic default route se jaata hai; usi AZ ka target shared zonal dependency se bachata hai.'},{text:'Asli DNS/HTTPS access aur failure wala raasta test karo',explain:'Route set hona aur "available" data asli destination ya app ka chalna prove nahi karte.'}],explain:'API se NAT banana route sahi hone ka saboot nahi. Waiter "available" dikhaye, tab app route lagao. Aakhri runtime test hi asli egress prove karta hai.'},
      {type:'triage',title:'🩺 NAT available hai, phir packages download kyun nahi ho rahe?',symptom:'Private app ka package HTTPS timeout ho raha hai. App ki table NAT ki taraf route karti hai; NAT State=available hai. NAT wale subnet ki asli route table dekho. Yeh saboot course ka example hai, Moto ka naapa hua packet nahi.',commands:[{cmd:'aws ec2 describe-nat-gateways --nat-gateway-ids nat-bad',out:'{"NatGateways":[{"NatGatewayId":"nat-bad","SubnetId":"subnet-wrong","State":"available","ConnectivityType":"public"}]}',clue:true,note:'NAT available dikh raha hai; subnet-wrong ka route association abhi pata nahi.'},{cmd:'aws ec2 describe-route-tables --filters Name=association.subnet-id,Values=subnet-wrong',out:'{"RouteTables":[{"RouteTableId":"rtb-isolated","Routes":[{"DestinationCidrBlock":"10.9.0.0/16","GatewayId":"local"}]}]}',clue:true,note:'NAT wale subnet mein IGW ka default route nahi hai. Isolated subnet ka public NAT IGW se IPv4 internet tak nahi pahunch sakta.'},{cmd:'aws ec2 describe-route-tables --route-table-ids rtb-app-a',out:'{"RouteTables":[{"Routes":[{"DestinationCidrBlock":"0.0.0.0/0","NatGatewayId":"nat-bad","State":"active"}]}]}',clue:false,note:'Pehla route hop hai; agle hop ki subnet routing tooti hai.'},{cmd:'aws ec2 describe-security-groups --group-ids sg-app',out:'{"SecurityGroups":[{"IpPermissionsEgress":[{"IpProtocol":"tcp","FromPort":443,"ToPort":443,"IpRanges":[{"CidrIp":"0.0.0.0/0"}]}]}]}',clue:false,note:'HTTPS bahar jaane ki permission hai. Is example mein NACL aur DNS bhi check hue; permission missing route nahi banati.'}],questions:[Q('Kaunsa saboot raaste ki sabse badi kami samjhata hai?','NAT subnet ki asli table mein IGW ki taraf 0.0.0.0/0 nahi hai',['NAT available hai, toh raasta pakka sahi hai, isliye wajah app CPU hai','App ka default route hai, toh NAT subnet ki table egress par asar nahi karti','App par public IPv4 nahi, isliye NAT ke liye app ko public EIP dena padega'],1,'Public NAT ko apne subnet mein IGW route chahiye. Available sirf resource ki state hai. Sirf app wala hop adhoora hai. NAT se bahar jaane ke liye app ko public IPv4 nahi chahiye.','resilient'),Q('Aisa repair kaunsa hai jo app ko private rakhe aur design waisa hi rahe?','Naya zonal NAT sahi public subnet mein banao aur usi AZ ka app route badlo',['App ko public subnet mein le jao aur downloads ke liye bada inbound access do','S3 gateway endpoint jodo aur maan lo ki saari package registries S3 route lengi','DB SG ka inbound 5432 source badlo, HTTPS ka wapsi route apne aap ban jaayega'],2,'Sahi public NAT/IGW design raasta theek karta hai. Ya phir exposure review karke NAT subnet ka sahi association lagao. App ko public karna security design badal deta hai. S3 endpoint har host cover nahi karta. DB SG route nahi banata.','resilient')]},
      (function(){const tasks=[{text:'AZ-a app → available public NAT-a (EIP ke saath) → IGW',check:s=>natOK(s,'a')},{text:'AZ-b app → apna alag available public NAT-b/EIP → IGW',check:s=>natOK(s,'b')},{text:'Same-region S3 gateway endpoint ke managed prefix routes dono app tables par hain',check:endpointOK},{text:'Active peer, CIDR overlap nahi; orders aur analytics ki tables mein dono routes',check:peerOK},{text:'Purane private apps/reader, chhota DB 5432 rule aur local routes bache rahe',check:preserved},{text:'Sirf planned resources: 2 chalte NAT / 2 EIP / 1 chalta S3 endpoint / 1 chalta peer',check:s=>(s.account.natGateways||[]).filter(n=>n.state!=='deleted').length===2&&(s.account.addresses||[]).length===2&&(s.account.vpcEndpoints||[]).filter(e=>e.state!=='deleted').length===1&&(s.account.vpcPeerings||[]).filter(p=>p.state!=='deleted').length===1}];return {type:'terminal',title:'🖥️ Mission: egress, S3 ka sasta raasta aur analytics peer',instructions:'Naye mission mein IDs pehle se tay hain: allocate-address se eipalloc-000000001/2, naye NAT nat-000000001/2 aur peer pcx-000000001 milenge. Output padho, available hone tak wait karo, phir route lagao. Saare 13 commands hints mein chalne layak likhe hain.',goal:'Do public subnets mein do NAT, har ek ka alag EIP, aur waiter. rtb-app-a/b ke default routes apne-apne AZ ke NAT par. S3 Gateway endpoint dono app tables par. vpc-shop↔vpc-analytics peer banao aur accept karo; rtb-orders mein analytics CIDR ka wapsi route aur rtb-analytics mein ShopKaro CIDR ka route. Sirf planned 2 NAT/2 EIP/1 S3 endpoint/1 peer rakho; purane resources aur permissions waise hi rakho. Simulator turant state badal deta hai; asli packet test alag hain.',account:seed(),tasks,solution:SOLUTION.slice(),success:AG.allOf(tasks),hints:SOLUTION.map((c,i)=>c+[' — pehle zonal NAT ka IPv4 allocation',' — doosre AZ ka alag IPv4 allocation',' — public-a subnet chuno, private app subnet nahi',' — route lagane se pehle NAT ke available hone ka wait',' — public-b + second allocation',' — doosre NAT ke available hone ka wait',' — app-a effective table',' — app-b apne AZ ka NAT le, shared NAT-a ka shortcut nahi',' — route associations se S3 prefix routes apne aap bante hain',' — non-overlapping VPCs ke beech request',' — accept karne se active hota hai; routes alag se chahiye',' — orders subnet se wapsi ka raasta',' — analytics ka bahar ka raasta; ab final state poori'][i]),successText:'Do alag zonal egress raaste, S3 service route aur dono taraf ka active peer: config theek ho gaya. Purana reader aur apps private aur scoped hain. Asli DNS, packets, SQL access, AZ recovery aur poora bill abhi bhi asli test maangte hain.'};})(),
      {type:'docker',title:'🐳 Real lab: NAT, gateway/interface endpoints aur peering',project:'09-nat-endpoint-peering',goal:'README ke ex1–ex5 chalao: setup dekho → asli scripts se banao → endpoint association hatao aur wapas lagao → peer aur flow subscription dekho → sirf apne resources ka cleanup.',why:'Asli AWS CLI aur Moto API data save karte hain. OS, app, SQL, packet ya DNS yahan nahi chalte; isliye asli connection chal raha hai, yeh daava nahi karte.',steps:[{text:'README Setup ke exports, phir ex1 setup. Sirf local route wali app table dekho.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 09-nat-endpoint-peering\n# README Setup exports isi terminal mein run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Shuru ki state: private app tables mein sirf local route; koi NAT, endpoint ya peer nahi.'},{text:'ex2: scripts padho aur chalao; do interface ENIs aur private DNS ka data dekho.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'{"Type":"Interface","State":"available","PrivateDNS":true,"ENIs":2}'},{text:'ex3: endpoint ka route table association hatao, phir jodo; count pehle 1, phir 2 aana chahiye.',cmd:'aws ec2 modify-vpc-endpoint --vpc-endpoint-id "$ENDPOINT" --remove-route-table-ids "$APP_RT_B"\naws ec2 modify-vpc-endpoint --vpc-endpoint-id "$ENDPOINT" --add-route-table-ids "$APP_RT_B"',expect:'{"Return":true}'},{text:'ex4: data review; ex5: cleanup. Moto delete hue endpoint ka record abhi bhi dikhata hai.',cmd:'aws ec2 describe-flow-logs --flow-log-ids "$FLOW" --query \'FlowLogs[0].{State:FlowLogStatus,Traffic:TrafficType,Destination:LogDestinationType}\'\nbash cleanup.sh',expect:'{"State":"ACTIVE","Traffic":"ALL","Destination":"s3"}'}],observe:Q('Gateway endpoint ka route hai aur FlowLogStatus ACTIVE hai. Asal mein kya pakka hua?','Route aur subscription ka data sahi hai; asli packets aur pahunche logs test nahi hue',['App ka S3 IAM access aur invoice ki permission apne aap mil gayi hai','NAT ka throughput aur multi-AZ recovery time describe commands ne naap liya','FlowLogStatus ACTIVE prove karta hai ki har packet destination app tak pahuncha'],3,'API config asli data ka saboot hai. Endpoint app ko access nahi deta. Describe commands load ya failover test nahi karte. ACTIVE subscription se logs pahunche, yeh prove nahi hota.','resilient')},
      {type:'quiz',bonus:true,title:'📝 SAA-style VPC decisions',questions:[
        Q('NAT processing ke bill ka zyaadatar hissa same-region S3 ka hai. Sabse kam extra kharche wala raasta?','Matching S3 traffic ke liye saari zaroori app route tables par gateway endpoint',['Har S3 request ke liye interface endpoints, route design bilkul waisa hi rakh kar','NAT gateway ka bada IP pool, kyunki zyada addresses se per-GB charge hat jaata hai','App ko public EIP do, taaki S3 IAM role aur endpoint policies ki zaroorat na rahe'],0,'Gateway ka raasta NAT processing bachata hai, aur gateway endpoint ka koi extra ghante/GB charge nahi. Paid S3 interface endpoint door se access ki zaroorat mein theek ho sakta hai. Zyada EIP processing nahi hataate. Public address IAM ki jagah nahi leta.','cost-optimized'),
        Q('Private EC2 ko IPv6 se bahar jaana hai, par bahar se IPv6 connection andar nahi aana chahiye. Kya chunoge?','Egress-only internet gateway, aur private subnet mein sahi ::/0 route',['Sirf IPv4 public NAT, bina DNS64/NAT64 ya IPv6 routing badle','S3 gateway endpoint, taaki har IPv6 internet jagah S3 prefix se match ho','Seedha public IGW route, aur maan lo ki route table inbound sessions rok degi'],1,'Egress-only IGW IPv6 ke liye sirf bahar jaane ka raasta hai. Sirf IPv4 wala design adhoora hai. S3 prefix sirf S3 ke liye hai. Aam IGW route egress-only wali rok nahi lagata.','secure'),
        Q('VPC A–B aur B–C ke peers hain. A ke app ko C chahiye. Agla sahi design kya hai?','Seedha A–C peer, routes aur security ke saath, ya soch-samajh kar bana transit hub',['Ek aur bilkul waisa A–B peer jodo, taaki traffic transit ho kar aage jaaye','A→C ka route pehle se bane B–C peer ID se do, bhale hi A us peer mein nahi','A mein NAT gateways badhao, taaki pehle wali peering ko transit ki taakat mile'],2,'Peering B ke through traffic aage nahi bhejti; seedha peer ya review kiya hua hub chahiye. Duplicate link ya NAT ki ginti transit nahi jodti, aur jo VPC peer mein nahi uska route target galat hai.','resilient'),
        Q('Interface endpoint par PrivateDNS on hai, phir bhi SDK timeout ho raha hai. Agla seedha network saboot?','Endpoint ENI ka SG 443, VPC DNS settings, source routes/NACL aur resolve hue addresses',['Sirf IAM policy ki length, kyunki har permission error TCP timeout hi deta hai','Sirf S3 bucket encryption, kyunki endpoint ka private IP bucket key se aata hai','Sirf EC2 ka public IP, kyunki interface endpoints ko public clients chahiye'],3,'DNS/SG/NACL/ENI ka saboot batata hai ki timeout kahan hai. Pahunch hone ke baad IAM denial aksar service error deta hai, timeout nahi. Bucket encryption aur public IPv4 ka private endpoint ke connection se lena-dena nahi.','high-performing'),
        Q('5 VPCs ka full direct mesh chahiye. Kitne connections, aur kya trade-off?','10 peers; transit nahi, routes/security har jagah; TGW ke central operations aur kharche se compare karo',['25 peers; square jaisa badhta hai, isliye har VPC ko routing ke liye khud se peer karna padta hai','5 peers; har VPC ka ek link apne aap poora transit access de deta hai','20 peers; requester aur accepter ke hisse alag-alag bill hone wale connections hain'],0,'N(N−1)/2 = 10 peers. Khud se link nahi hota, aur accepter ka hissa alag nahi ginte. 5 hub attachments transit tabhi dete hain jab hub ki routing set ho.','cost-optimized'),
        Q('Analytics peer active hai; jaane ka route hai; DB ki wapsi wali table mein analytics ka route nahi. Fix?','Orders ki asli table mein analytics ke jawaab wala CIDR route usi peer par jodo',['Ek aur poori duniya wala DB SG rule jodo, taaki allowed source se routing samajh aa jaaye','S3 endpoint ka private DNS badlo, taaki PostgreSQL packets ko S3 ka managed prefix mile','Analytics VPC mein ek aur NAT banao, kyunki accept hui peering public EIP use karti hai'],1,'Dono taraf ke private raaste chahiye. SG allow route nahi banata. S3 DNS/prefix PostgreSQL ki routing nahi hai. Peering ko NAT ya public EIP nahi chahiye.','resilient'),
        Q('Regional NAT saare app AZ mein ek hi gateway ID use karta hai. Bill ke baare mein sahi baat?','Configured AZ-ghante aur processed GB dekho; ek ID ka matlab ek AZ ka charge nahi',['Ek regional gateway ID ka bill ek hi zonal ghante ka aata hai, chahe kai AZ active hon','Regional mode saare NAT processing charges hata deta hai, kyunki routing AWS sambhalta hai','Regional mode har private service ki IAM policy aur public IPv4 ka kharcha hata deta hai'],2,'Regional NAT ka daam har configured AZ-ghante + processing + baaki lagu charges par banta hai. AWS routing sambhale, phir bhi GB, IAM aur public address ki baatein rehti hain.','cost-optimized'),
        Q('Reachability Analyzer kehta hai ki config ke hisaab se raasta hai. Ab kya runtime test bacha hai?','App ka asli listener, DNS/SDK ka behaviour, permission aur sahi jawaab aana',['Har route aur SG rule bana hai ya nahi, kyunki analyzer asli packets bhejta hai','Packet ka andar ka data dikhta hai ya nahi, kyunki analyzer har app body pakadta hai','Kya ASG har attached ENI ko database ki permission apne aap deta hai'],3,'Analyzer sirf config dekhta hai, asli packets ya app ka data/health nahi. App, DNS, permission aur data ke test alag hain. ASG DB credentials nahi deta.','high-performing'),
      ]},
    ],
    interview:{title:'🎤 Network review follow-ups',instructions:'Destination, permissions, failure ka raasta aur bill samjhao; naare nahi, saboot chuno.',questions:[
      Q('Dono app AZ NAT-a use karte hain. Zaroorat: AZ-a jaaye tab bhi chale. Sabse achha zonal design?','Har active AZ mein apna public NAT/EIP aur default route; dependencies bhi check karo',['Ek hi NAT-a rakho par uske EIP badha do, taaki woh kai AZ mein phail jaaye','Dono workers private-a mein le jao, taaki AZ jaane par egress routes ek jaise rahein','Active analytics peer se doosri VPC ka IGW udhaar le lo, bina extra design ke'],0,'Zonal NAT ki jagah ek shared AZ dependency hai. Zyada EIP mode nahi badalte. Workers ek jagah karna resilience aur kam karta hai. Peering doosri VPC ka IGW transit ke liye nahi deti.','resilient'),
      Q('5 services, har ek ka interface endpoint, 3 AZ mein. Fixed kharche ka input kya hai?','Har ghante 15 endpoint-AZ ghante, plus data aur region ke lagu charges',['Ek hi endpoint ka ghante ka charge, kyunki paanchon services ka VPC ID same hai','Kul 3 endpoint ghante, kyunki chune AZ ki ginti service ki ginti par bhari hai','Kul 5 endpoint ghante, kyunki private DNS har AZ wala hissa hata deta hai'],1,'Endpoint/service × chune hue AZ hi fixed ghanton ka multiplier hai. VPC ID ya private DNS service endpoints ko ek nahi karte. Har service/region ka exact daam phir bhi check karo.','cost-optimized'),
      Q('Saikdon customer VPCs ke CIDR overlap hote hain; sirf ek internal API dikhani hai. Kya chunoge?','Service-level PrivateLink endpoint design, provider aur consumer ki scoped permissions ke saath',['Same CIDRs ke saath full peering mesh, kyunki alag account IDs routes ko alag kar dete hain','Bina CIDR planning ke TGW full-network routing, kyunki attachments clients ke CIDR badal dete hain','Internet-facing NAT gateways jo custom ports par consumers ke inbound connections lete hain'],2,'PrivateLink sirf service ka access deta hai aur overlap wale customer networks mein bhi chal sakta hai. Peering mein overlap nahi chalta. TGW CIDR nahi badalta. NAT public inbound API ka darwaza nahi hai.','secure'),
      Q('Ek ENI par Flow Log mein REJECT aaya. Yeh record kya batata hai?','IP flow reject hone ka data; SG/NACL dekho aur raaste se mila kar samjho',['App ke HTTP jawaab ne us customer ki payment permission reject ki','Har route sahi hai, kyunki records sirf safal sessions ke hi bante hain','Packet ke data mein woh exact SQL query hai jo database validation mein fail hui'],3,'Flow data mein addresses, ports aur action hote hain; app ka data ya SQL/HTTP ki business wajah nahi. Route aur firewall ka saboot mila kar dekhna padta hai.','secure'),
      {terminal:(function(){const a=seed();a.vpcEndpoints=[{id:'vpce-s3-existing',type:'Gateway',vpcId:'vpc-shop',serviceName:'com.amazonaws.ap-south-1.s3',state:'available',prefixListId:'pl-s3',routeTableIds:['rtb-app-a']}];a.routeTables.find(t=>t.id==='rtb-app-a').routes.push({prefixListId:'pl-s3',target:'vpce-s3-existing',type:'endpoint',managed:true,state:'active'});const tasks=[{text:'Pehle wala S3 endpoint app-a aur app-b dono par theek; dono managed prefix routes ke saath',check:endpointOK},{text:'VPC ka ALL Flow Log subscription pehle se bane private shop-flowlogs bucket ki taraf',check:s=>(s.account.flowLogs||[]).some(f=>f.resourceId==='vpc-shop'&&f.trafficType==='ALL'&&f.state==='ACTIVE'&&f.destinationType==='s3'&&f.destination==='arn:aws:s3:::shop-flowlogs')},{text:'Purane reader/apps/routes bache rahe; koi duplicate S3 endpoint nahi',check:s=>preserved(s)&&(s.account.vpcEndpoints||[]).filter(e=>e.state!=='deleted').length===1}];const solution=['aws ec2 modify-vpc-endpoint --vpc-endpoint-id vpce-s3-existing --add-route-table-ids rtb-app-b','aws ec2 create-flow-logs --resource-type VPC --resource-ids vpc-shop --traffic-type ALL --log-destination-type s3 --log-destination arn:aws:s3:::shop-flowlogs'];return {title:'🖥️ Pehle wala endpoint theek karo + diagnostic data set karo',goal:'Pehle wale vpce-s3-existing ko rtb-app-b se bhi jodo; naya mat banao. vpc-shop ke ALL flow data ka S3 destination arn:aws:s3:::shop-flowlogs set karo. Packet ya log pahunchne ka daava mat karo.',account:a,tasks,success:AG.allOf(tasks),hints:solution.slice(),solution,successText:'Pehle wale endpoint ka association aur diagnostic subscription ka data ready hai. Destination ki asli permissions, pahunche log objects aur packet test abhi bhi check karne hain.'};})()},
    ]},
    success:['NAT, gateway/interface endpoint aur peer ka kaam alag-alag chun sakta hoon','Zonal vs Regional NAT, aur kharche/resilience ki maani hui baatein samjha sakta hoon','Dono taraf ke routes aur subnets ke asli associations dekh aur theek kar sakta hoon','Config ke data aur asli network/app ke saboot ka farak bata sakta hoon'],
    homework:'<p><b>Optional, sirf approved asli AWS sandbox mein (paisa lagega):</b> region ke aaj ke NAT/IPv4/endpoint/transfer/log ke daam nikaalo. Har AZ ka zonal NAT route ya review kiya hua Regional NAT chuno. Private app se ek approved HTTPS destination test karo. S3 gateway route aur IAM access compare karo. CIDR overlap se bach kar peer aur dono routes banao. Endpoint aur Flow Log delivery ki permissions review karke asli SDK/SQL aur log objects dekho. Asli sensitive DB ko mat chhuo. Cleanup: endpoint associations/endpoints, Flow Log subscriptions/destination objects, peering routes/peer, NAT (deleted hone tak wait), EIPs, test instances, SGs/subnets/route tables/IGW/VPC delete karo. NAT delete karne se EIP release nahi hota. Doosre logon ke shared resources ko reset mat karo.</p>',
    cards:[{front:'Zonal public NAT ke do routing hops kaun se hain?',back:'App ka default route → usi AZ ka NAT; NAT subnet ka default route → IGW. Public NAT EIP use karta hai; private app ko public IPv4 nahi chahiye.'},{front:'Regional NAT matlab sirf ek AZ ki fees?',back:'Nahi. Regional mode wahi AZ cover karta hai jahan app chal rahi hai; configured AZ-ghante aur processed GB ka bill banta hai. Zonal placement ke niyam alag hain.'},{front:'S3 gateway endpoint vs interface endpoint?',back:'Gateway: route table mein service prefix, same-region S3/DynamoDB ke liye, koi extra ghante/GB fees nahi. Interface: supported service ke liye private ENIs; har service/AZ ke ghante aur data ka kharcha.'},{front:'Endpoint policy kya permission deti hai?',back:'Endpoint policy ek extra boundary hai. IAM, bucket policy aur Deny phir bhi check hote hain; sirf route se GetObject ki permission nahi milti.'},{front:'Peering active hai, phir bhi timeout: kya dekhoge?',back:'Source ki asli table, wapsi ki asli table, SG/NACL, DNS aur app. Peering accept karne se dono routes apne aap nahi lagte.'},{front:'Full mesh formula?',back:'N×(N−1)/2 peers: 5→10; 10→45. TGW ke N attachments mesh sambhalna aasaan karte hain, par routes, segmentation aur kharcha phir bhi soch kar tay karo.'},{front:'Flow Logs vs Reachability Analyzer: farak kya hai?',back:'Flow Logs asli IP flow ka data dikhate hain, packet ka andar ka data nahi. Reachability Analyzer sirf config se raasta dekhta hai, asli packet ya app health test nahi karta.'},{front:'S3 1,024 GB NAT saving?',back:'Lagbhag $0.045/GB par matching gateway endpoint se $46.08/mahina ki processing bachti hai. Zaroori NAT ke fixed ghante aur baaki internet traffic ka kharcha bacha rehta hai.'}],
  }]);
})();
